export type ParsedSponsorInstruction<
  TProgram extends string = typeof MYBARPOOL_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The sponsor; pays `amount`, the `Sponsorship` rent on first call, and the transaction fee. */
    sponsor: TAccountMetas[0];
    /** PROGRAM §3.1 `PlatformConfig`; read for `paused` and the token's `max_sponsorship`. */
    config: TAccountMetas[1];
    /** PROGRAM §3.2 `GameRecord`, the pool's game (`has_one`); read for status and kickoff. */
    game: TAccountMetas[2];
    /** PROGRAM §3.3 `Pool`, re-derived from its own fields. */
    pool: TAccountMetas[3];
    /**
     * PROGRAM §3.4 vault at `["vault", pool]` with the stored bump; `pool.vault` is the
     * only address `sponsor` accepts for it.
     */
    vault: TAccountMetas[4];
    /** PROGRAM §3.7 `Sponsorship` at `["sponsorship", pool, sponsor]`; created on first call. */
    sponsorship: TAccountMetas[5];
    /** The pool's mint (`address = pool.mint`); SPL pools only. */
    mint?: TAccountMetas[6] | undefined;
    /** The sponsor's token account for the mint; SPL pools only. */
    sponsorTokenAccount?: TAccountMetas[7] | undefined;
    /** The pool's token program (checked against `pool.token_program`); SPL pools only. */
    tokenProgram?: TAccountMetas[8] | undefined;
    systemProgram: TAccountMetas[9];
    eventAuthority: TAccountMetas[10];
    program: TAccountMetas[11];
  };
  data: SponsorInstructionData;
};

export function parseSponsorInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSponsorInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 12,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === MYBARPOOL_PROGRAM_ADDRESS ? undefined : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      sponsor: getNextAccount(),
      config: getNextAccount(),
      game: getNextAccount(),
      pool: getNextAccount(),
      vault: getNextAccount(),
      sponsorship: getNextAccount(),
      mint: getNextOptionalAccount(),
      sponsorTokenAccount: getNextOptionalAccount(),
      tokenProgram: getNextOptionalAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getSponsorInstructionDataDecoder().decode(instruction.data),
  };
}
